import timeit
import functools
import numpy as np

N = 1_000_000
data = list(range(N))
arr = np.arange(N)

def sum_loop(xs):
    total = 0
    for x in xs:
        total += x * x
    return total

def sum_comprehension(xs):
    return sum(x * x for x in xs)

def sum_vectorized(a):
    return int((a * a).sum())

# Expensive pure function called with repeating arguments
@functools.lru_cache(maxsize=None)
def fib(n):
    return n if n < 2 else fib(n - 1) + fib(n - 2)

if __name__ == "__main__":
    t_loop = timeit.timeit(lambda: sum_loop(data), number=3) / 3
    t_comp = timeit.timeit(lambda: sum_comprehension(data), number=3) / 3
    t_vec = timeit.timeit(lambda: sum_vectorized(arr), number=3) / 3
    print(f"loop:          {t_loop:.4f}s")
    print(f"comprehension: {t_comp:.4f}s")
    print(f"vectorized:    {t_vec:.4f}s  ({t_loop / t_vec:.0f}x vs loop)")

    fib(100)  # fills the cache via recursion
    print("cache info:", fib.cache_info())
